package com.github.rcubedev.utils.event.generated;

import com.github.rcubedev.utils.event.api.Event;
import org.jetbrains.annotations.ApiStatus;

import java.util.List;

/**
 * SPI for compile-time generated subscriber invoker factories.
 *
 * @apiNote This interface is implemented solely by classes generated by the
 *          annotation processor and should not be implemented directly
 * @param <T> the subscriber target class type
 * @param <B> the base event type supported by this factory
 */
@ApiStatus.NonExtendable
public interface SubscriberInvokerFactory<T, B extends Event> {

    /**
     * Returns the class of the subscriber target handled by this factory.
     *
     * @return the target class
     */
    Class<T> targetClass();

    /**
     * Returns a list of pre-compiled invokers mapping to event handler methods on the target class.
     *
     * @return list of event processor invokers
     */
    List<EventSubscriberInvoker<T, ? extends B>> invokers();
}
